#!/usr/bin/env node
// FYP.STUDIO — Admin Extra: Categorías, Settings, Clientes, IA (Parte 3)
// Ejecutar desde la raíz del proyecto: node setup_admin_extra.js
const fs = require('fs')
const path = require('path')
const files = {}

files["app/admin/layout.tsx"] = "// app/admin/layout.tsx\nimport { redirect } from 'next/navigation'\nimport { createClient } from '@/lib/supabase/server'\nimport AdminSidebar from '@/components/admin/AdminSidebar'\n\nexport default async function AdminLayout({ children }: { children: React.ReactNode }) {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('*, business:businesses(*)')\n    .eq('user_id', user.id)\n    .single()\n\n  const needsOnboarding = !profile || !profile.business_id\n  const business = profile?.business ?? null\n\n  return (\n    <div className=\"flex h-screen bg-[#f9f9f8] overflow-hidden\">\n      {!needsOnboarding && (\n        <AdminSidebar business={business} userEmail={user.email ?? ''} />\n      )}\n      <main className={`flex-1 overflow-y-auto ${needsOnboarding ? 'w-full' : ''}`}>\n        {business?.subscription_status === 'suspended' && (\n          <div className=\"bg-red-500 text-white text-xs text-center py-2 px-4 font-medium\">\n            ⚠️ Suscripción suspendida — contactá soporte para reactivar\n          </div>\n        )}\n        <div className={needsOnboarding ? '' : 'p-6 lg:p-8 max-w-6xl mx-auto'}>\n          {children}\n        </div>\n      </main>\n    </div>\n  )\n}\n"

files["app/admin/categories/page.tsx"] = "// app/admin/categories/page.tsx\nimport { createClient } from '@/lib/supabase/server'\nimport { redirect } from 'next/navigation'\nimport { Tag } from 'lucide-react'\nimport CategoryManager from './CategoryManager'\nimport type { Category } from '@/types'\n\nexport const metadata = { title: 'Categorías' }\n\nexport default async function CategoriesPage() {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('business_id')\n    .eq('user_id', user.id)\n    .single()\n\n  if (!profile?.business_id) redirect('/admin/onboarding')\n\n  const { data: categories } = await supabase\n    .from('categories')\n    .select('*')\n    .eq('business_id', profile.business_id)\n    .order('sort_order')\n    .order('created_at')\n\n  return (\n    <div className=\"space-y-6 animate-fade-in\">\n      <div className=\"flex items-center justify-between\">\n        <div>\n          <h1 className=\"text-2xl font-semibold tracking-tight\">Categorías</h1>\n          <p className=\"text-sm text-gray-400 mt-0.5\">\n            Organizá tus productos por categoría\n          </p>\n        </div>\n      </div>\n\n      <CategoryManager\n        businessId={profile.business_id}\n        initialCategories={(categories ?? []) as Category[]}\n      />\n    </div>\n  )\n}\n"

files["app/admin/categories/CategoryManager.tsx"] = "// app/admin/categories/CategoryManager.tsx\n'use client'\nimport { useState } from 'react'\nimport { createClient } from '@/lib/supabase/client'\nimport { slugify, cn } from '@/lib/utils'\nimport { Plus, Tag, Loader2, Eye, EyeOff, GripVertical } from 'lucide-react'\nimport type { Category } from '@/types'\n\nexport default function CategoryManager({\n  businessId,\n  initialCategories,\n}: {\n  businessId: string\n  initialCategories: Category[]\n}) {\n  const supabase = createClient()\n  const [categories, setCategories] = useState<Category[]>(initialCategories)\n  const [newName, setNewName] = useState('')\n  const [creating, setCreating] = useState(false)\n  const [loadingId, setLoadingId] = useState<string | null>(null)\n  const [error, setError] = useState<string | null>(null)\n\n  async function createCategory(e: React.FormEvent) {\n    e.preventDefault()\n    if (!newName.trim()) return\n    setCreating(true)\n    setError(null)\n\n    const slug = slugify(newName) + '-' + Math.random().toString(36).slice(2, 5)\n    const { data, error: err } = await supabase\n      .from('categories')\n      .insert({\n        business_id: businessId,\n        name: newName.trim(),\n        slug,\n        sort_order: categories.length,\n        active: true,\n      })\n      .select('*')\n      .single()\n\n    if (err) {\n      setError(err.message)\n    } else if (data) {\n      setCategories(prev => [...prev, data as Category])\n      setNewName('')\n    }\n    setCreating(false)\n  }\n\n  async function toggleActive(cat: Category) {\n    setLoadingId(cat.id)\n    const { data } = await supabase\n      .from('categories')\n      .update({ active: !cat.active })\n      .eq('id', cat.id)\n      .select('*')\n      .single()\n\n    if (data) {\n      setCategories(prev => prev.map(c => c.id === cat.id ? data as Category : c))\n    }\n    setLoadingId(null)\n  }\n\n  const active = categories.filter(c => c.active)\n  const inactive = categories.filter(c => !c.active)\n\n  return (\n    <div className=\"space-y-5\">\n      {/* Formulario nueva categoría */}\n      <div className=\"bg-white rounded-2xl border border-gray-100 p-5\">\n        <p className=\"text-sm font-medium text-gray-700 mb-3\">Nueva categoría</p>\n        <form onSubmit={createCategory} className=\"flex gap-3\">\n          <input\n            type=\"text\"\n            value={newName}\n            onChange={e => setNewName(e.target.value)}\n            placeholder=\"Ej: Hamburguesas, Bebidas, Accesorios...\"\n            className=\"input-base flex-1\"\n            disabled={creating}\n          />\n          <button\n            type=\"submit\"\n            disabled={creating || !newName.trim()}\n            className=\"flex items-center gap-2 rounded-xl bg-black px-4 py-2.5 text-sm font-medium\n                       text-white hover:bg-gray-800 transition-colors disabled:opacity-40 shrink-0\n                       active:scale-[0.98]\"\n          >\n            {creating\n              ? <Loader2 size={14} className=\"animate-spin\" />\n              : <Plus size={14} />\n            }\n            Crear\n          </button>\n        </form>\n        {error && (\n          <p className=\"text-xs text-red-600 mt-2\">{error}</p>\n        )}\n      </div>\n\n      {/* Lista de categorías */}\n      {categories.length === 0 ? (\n        <div className=\"rounded-2xl border-2 border-dashed border-gray-200 p-14 text-center\">\n          <Tag size={28} className=\"mx-auto text-gray-200 mb-3\" />\n          <p className=\"text-sm font-medium text-gray-400\">Sin categorías todavía</p>\n          <p className=\"text-xs text-gray-300 mt-1\">Creá categorías para organizar tu catálogo</p>\n        </div>\n      ) : (\n        <div className=\"bg-white rounded-2xl border border-gray-100 overflow-hidden\">\n          {/* Activas */}\n          {active.length > 0 && (\n            <div>\n              <div className=\"px-5 py-3 border-b border-gray-100 bg-gray-50/50\">\n                <p className=\"text-xs font-medium text-gray-500\">\n                  Activas ({active.length})\n                </p>\n              </div>\n              {active.map((cat, i) => (\n                <CategoryRow\n                  key={cat.id}\n                  cat={cat}\n                  loading={loadingId === cat.id}\n                  onToggle={() => toggleActive(cat)}\n                  isLast={i === active.length - 1 && inactive.length === 0}\n                />\n              ))}\n            </div>\n          )}\n\n          {/* Inactivas */}\n          {inactive.length > 0 && (\n            <div>\n              <div className=\"px-5 py-3 border-b border-gray-100 bg-gray-50/50\">\n                <p className=\"text-xs font-medium text-gray-400\">\n                  Inactivas ({inactive.length})\n                </p>\n              </div>\n              {inactive.map((cat, i) => (\n                <CategoryRow\n                  key={cat.id}\n                  cat={cat}\n                  loading={loadingId === cat.id}\n                  onToggle={() => toggleActive(cat)}\n                  isLast={i === inactive.length - 1}\n                />\n              ))}\n            </div>\n          )}\n        </div>\n      )}\n    </div>\n  )\n}\n\nfunction CategoryRow({\n  cat,\n  loading,\n  onToggle,\n  isLast,\n}: {\n  cat: Category\n  loading: boolean\n  onToggle: () => void\n  isLast: boolean\n}) {\n  return (\n    <div className={cn(\n      'flex items-center gap-4 px-5 py-3.5 hover:bg-gray-50/50 transition-colors',\n      !isLast && 'border-b border-gray-50'\n    )}>\n      <GripVertical size={14} className=\"text-gray-200 shrink-0\" />\n\n      <div className=\"flex-1 min-w-0\">\n        <p className={cn(\n          'text-sm font-medium',\n          cat.active ? 'text-gray-900' : 'text-gray-400'\n        )}>\n          {cat.name}\n        </p>\n        <p className=\"text-xs text-gray-400 font-mono\">/{cat.slug}</p>\n      </div>\n\n      <span className={cn(\n        'badge',\n        cat.active ? 'bg-green-50 text-green-700' : 'bg-gray-100 text-gray-400'\n      )}>\n        {cat.active ? 'Activa' : 'Inactiva'}\n      </span>\n\n      <button\n        onClick={onToggle}\n        disabled={loading}\n        className=\"flex h-8 w-8 items-center justify-center rounded-lg text-gray-400\n                   hover:bg-gray-100 hover:text-gray-700 transition-colors disabled:opacity-40\"\n        title={cat.active ? 'Desactivar' : 'Activar'}\n      >\n        {loading\n          ? <Loader2 size={14} className=\"animate-spin\" />\n          : cat.active\n            ? <EyeOff size={14} />\n            : <Eye size={14} />\n        }\n      </button>\n    </div>\n  )\n}\n"

files["app/admin/settings/page.tsx"] = "// app/admin/settings/page.tsx\nimport { createClient } from '@/lib/supabase/server'\nimport { redirect } from 'next/navigation'\nimport SettingsForm from './SettingsForm'\nimport type { Business } from '@/types'\n\nexport const metadata = { title: 'Configuración' }\n\nexport default async function SettingsPage() {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('business_id, business:businesses(*)')\n    .eq('user_id', user.id)\n    .single()\n\n  if (!profile?.business_id) redirect('/admin/onboarding')\n\n  return (\n    <div className=\"space-y-6 animate-fade-in\">\n      <div>\n        <h1 className=\"text-2xl font-semibold tracking-tight\">Configuración</h1>\n        <p className=\"text-sm text-gray-400 mt-0.5\">Datos y apariencia de tu negocio</p>\n      </div>\n      <SettingsForm business={profile.business as Business} />\n    </div>\n  )\n}\n"

files["app/admin/settings/SettingsForm.tsx"] = "// app/admin/settings/SettingsForm.tsx\n'use client'\nimport { useState } from 'react'\nimport { createClient } from '@/lib/supabase/client'\nimport { Check, Loader2, Upload, ExternalLink } from 'lucide-react'\nimport type { Business } from '@/types'\n\nconst CURRENCIES = [\n  { value: 'UYU', label: 'UYU — Peso uruguayo' },\n  { value: 'ARS', label: 'ARS — Peso argentino' },\n  { value: 'CLP', label: 'CLP — Peso chileno' },\n  { value: 'COP', label: 'COP — Peso colombiano' },\n  { value: 'MXN', label: 'MXN — Peso mexicano' },\n  { value: 'USD', label: 'USD — Dólar' },\n  { value: 'BRL', label: 'BRL — Real brasileño' },\n]\n\nexport default function SettingsForm({ business }: { business: Business }) {\n  const supabase = createClient()\n\n  const [saving, setSaving] = useState(false)\n  const [saved, setSaved] = useState(false)\n  const [error, setError] = useState<string | null>(null)\n  const [uploadingLogo, setUploadingLogo] = useState(false)\n  const [uploadingBanner, setUploadingBanner] = useState(false)\n\n  const [name, setName] = useState(business.name ?? '')\n  const [whatsapp, setWhatsapp] = useState(business.whatsapp ?? '')\n  const [address, setAddress] = useState(business.address ?? '')\n  const [currency, setCurrency] = useState(business.currency ?? 'UYU')\n  const [primaryColor, setPrimaryColor] = useState(business.primary_color ?? '#000000')\n  const [secondaryColor, setSecondaryColor] = useState(business.secondary_color ?? '#ffffff')\n  const [logoUrl, setLogoUrl] = useState(business.logo_url ?? '')\n  const [bannerUrl, setBannerUrl] = useState(business.banner_url ?? '')\n  const [instagram, setInstagram] = useState(business.instagram ?? '')\n  const [tiktok, setTiktok] = useState(business.tiktok ?? '')\n  const [website, setWebsite] = useState(business.website ?? '')\n\n  async function uploadFile(\n    e: React.ChangeEvent<HTMLInputElement>,\n    type: 'logo' | 'banner'\n  ) {\n    const file = e.target.files?.[0]\n    if (!file) return\n    if (type === 'logo') setUploadingLogo(true)\n    else setUploadingBanner(true)\n\n    const ext = file.name.split('.').pop()\n    const path = `${business.id}/${type}-${Date.now()}.${ext}`\n    const { data, error } = await supabase.storage\n      .from('product-images')\n      .upload(path, file, { upsert: true })\n\n    if (!error && data) {\n      const { data: url } = supabase.storage\n        .from('product-images')\n        .getPublicUrl(data.path)\n      if (type === 'logo') setLogoUrl(url.publicUrl)\n      else setBannerUrl(url.publicUrl)\n    }\n    if (type === 'logo') setUploadingLogo(false)\n    else setUploadingBanner(false)\n    e.target.value = ''\n  }\n\n  async function handleSave(e: React.FormEvent) {\n    e.preventDefault()\n    setSaving(true)\n    setSaved(false)\n    setError(null)\n\n    const { error } = await supabase\n      .from('businesses')\n      .update({\n        name: name.trim(),\n        whatsapp: whatsapp.trim() || null,\n        address: address.trim() || null,\n        currency,\n        primary_color: primaryColor,\n        secondary_color: secondaryColor,\n        logo_url: logoUrl || null,\n        banner_url: bannerUrl || null,\n        instagram: instagram.trim() || null,\n        tiktok: tiktok.trim() || null,\n        website: website.trim() || null,\n      })\n      .eq('id', business.id)\n\n    if (error) {\n      setError(error.message)\n    } else {\n      setSaved(true)\n      setTimeout(() => setSaved(false), 3000)\n    }\n    setSaving(false)\n  }\n\n  return (\n    <form onSubmit={handleSave} className=\"space-y-6 max-w-2xl\">\n\n      {/* Sección: Datos básicos */}\n      <Section title=\"Datos del negocio\">\n        <div>\n          <label className=\"field-label\">Nombre del negocio</label>\n          <input type=\"text\" required value={name} onChange={e => setName(e.target.value)}\n            className=\"input-base\" placeholder=\"Ej: Burger House\" />\n        </div>\n\n        <div className=\"grid grid-cols-2 gap-4\">\n          <div>\n            <label className=\"field-label\">WhatsApp</label>\n            <input type=\"text\" value={whatsapp} onChange={e => setWhatsapp(e.target.value)}\n              className=\"input-base\" placeholder=\"59899123456\" />\n            <p className=\"text-xs text-gray-400 mt-1\">Sin espacios ni guiones</p>\n          </div>\n          <div>\n            <label className=\"field-label\">Moneda</label>\n            <select value={currency} onChange={e => setCurrency(e.target.value)} className=\"input-base\">\n              {CURRENCIES.map(c => (\n                <option key={c.value} value={c.value}>{c.label}</option>\n              ))}\n            </select>\n          </div>\n        </div>\n\n        <div>\n          <label className=\"field-label\">Dirección</label>\n          <input type=\"text\" value={address} onChange={e => setAddress(e.target.value)}\n            className=\"input-base\" placeholder=\"Av. 18 de Julio 1234, Montevideo\" />\n        </div>\n      </Section>\n\n      {/* Sección: Apariencia */}\n      <Section title=\"Apariencia\">\n        {/* Logo */}\n        <div>\n          <label className=\"field-label\">Logo</label>\n          <div className=\"flex items-center gap-4\">\n            <div className=\"h-16 w-16 rounded-xl border border-gray-200 overflow-hidden bg-gray-50 shrink-0\">\n              {logoUrl\n                ? <img src={logoUrl} alt=\"Logo\" className=\"h-full w-full object-cover\" />\n                : <div className=\"h-full w-full flex items-center justify-center text-xs text-gray-300\">Logo</div>\n              }\n            </div>\n            <div className=\"flex-1\">\n              <label className={`flex items-center gap-2 rounded-xl border border-dashed border-gray-200\n                                 px-4 py-2.5 text-sm text-gray-500 cursor-pointer\n                                 hover:border-gray-400 hover:text-gray-700 transition-colors w-fit\n                                 ${uploadingLogo ? 'opacity-50 cursor-not-allowed' : ''}`}>\n                {uploadingLogo\n                  ? <Loader2 size={14} className=\"animate-spin\" />\n                  : <Upload size={14} />\n                }\n                {uploadingLogo ? 'Subiendo...' : 'Subir logo'}\n                <input type=\"file\" accept=\"image/*\" className=\"hidden\"\n                  onChange={e => uploadFile(e, 'logo')} disabled={uploadingLogo} />\n              </label>\n              {logoUrl && (\n                <input type=\"text\" value={logoUrl} onChange={e => setLogoUrl(e.target.value)}\n                  className=\"input-base mt-2 text-xs\" placeholder=\"O pegá una URL\" />\n              )}\n            </div>\n          </div>\n        </div>\n\n        {/* Banner */}\n        <div>\n          <label className=\"field-label\">Banner de la tienda</label>\n          <div className=\"space-y-2\">\n            {bannerUrl && (\n              <div className=\"h-24 rounded-xl overflow-hidden border border-gray-200\">\n                <img src={bannerUrl} alt=\"Banner\" className=\"h-full w-full object-cover\" />\n              </div>\n            )}\n            <label className={`flex items-center gap-2 rounded-xl border border-dashed border-gray-200\n                               px-4 py-2.5 text-sm text-gray-500 cursor-pointer\n                               hover:border-gray-400 hover:text-gray-700 transition-colors w-fit\n                               ${uploadingBanner ? 'opacity-50 cursor-not-allowed' : ''}`}>\n              {uploadingBanner\n                ? <Loader2 size={14} className=\"animate-spin\" />\n                : <Upload size={14} />\n              }\n              {uploadingBanner ? 'Subiendo...' : 'Subir banner'}\n              <input type=\"file\" accept=\"image/*\" className=\"hidden\"\n                onChange={e => uploadFile(e, 'banner')} disabled={uploadingBanner} />\n            </label>\n            <input type=\"text\" value={bannerUrl} onChange={e => setBannerUrl(e.target.value)}\n              className=\"input-base text-xs\" placeholder=\"O pegá una URL de imagen\" />\n          </div>\n        </div>\n\n        {/* Colores */}\n        <div className=\"grid grid-cols-2 gap-4\">\n          <div>\n            <label className=\"field-label\">Color principal</label>\n            <div className=\"flex items-center gap-3\">\n              <input type=\"color\" value={primaryColor}\n                onChange={e => setPrimaryColor(e.target.value)}\n                className=\"h-10 w-10 rounded-lg border border-gray-200 cursor-pointer p-0.5 bg-white\" />\n              <input type=\"text\" value={primaryColor}\n                onChange={e => setPrimaryColor(e.target.value)}\n                className=\"input-base font-mono text-sm flex-1\" />\n            </div>\n          </div>\n          <div>\n            <label className=\"field-label\">Color secundario</label>\n            <div className=\"flex items-center gap-3\">\n              <input type=\"color\" value={secondaryColor}\n                onChange={e => setSecondaryColor(e.target.value)}\n                className=\"h-10 w-10 rounded-lg border border-gray-200 cursor-pointer p-0.5 bg-white\" />\n              <input type=\"text\" value={secondaryColor}\n                onChange={e => setSecondaryColor(e.target.value)}\n                className=\"input-base font-mono text-sm flex-1\" />\n            </div>\n          </div>\n        </div>\n\n        {/* Preview de colores */}\n        <div className=\"rounded-xl border border-gray-100 p-4 bg-gray-50\">\n          <p className=\"text-xs text-gray-400 mb-3\">Preview</p>\n          <button type=\"button\" className=\"rounded-xl px-5 py-2.5 text-sm font-medium transition-colors\"\n            style={{ background: primaryColor, color: secondaryColor }}>\n            Botón de ejemplo\n          </button>\n        </div>\n      </Section>\n\n      {/* Sección: Redes sociales */}\n      <Section title=\"Redes sociales\">\n        <div className=\"grid grid-cols-1 gap-4\">\n          <div>\n            <label className=\"field-label\">Instagram</label>\n            <div className=\"relative\">\n              <span className=\"absolute left-3.5 top-1/2 -translate-y-1/2 text-sm text-gray-400\">@</span>\n              <input type=\"text\" value={instagram} onChange={e => setInstagram(e.target.value)}\n                className=\"input-base pl-8\" placeholder=\"tucomercio\" />\n            </div>\n          </div>\n          <div>\n            <label className=\"field-label\">TikTok</label>\n            <div className=\"relative\">\n              <span className=\"absolute left-3.5 top-1/2 -translate-y-1/2 text-sm text-gray-400\">@</span>\n              <input type=\"text\" value={tiktok} onChange={e => setTiktok(e.target.value)}\n                className=\"input-base pl-8\" placeholder=\"tucomercio\" />\n            </div>\n          </div>\n          <div>\n            <label className=\"field-label\">Sitio web</label>\n            <input type=\"url\" value={website} onChange={e => setWebsite(e.target.value)}\n              className=\"input-base\" placeholder=\"https://tucomercio.com\" />\n          </div>\n        </div>\n      </Section>\n\n      {/* Info del plan */}\n      <div className=\"rounded-2xl bg-gray-50 border border-gray-100 px-5 py-4\">\n        <div className=\"flex items-center justify-between\">\n          <div>\n            <p className=\"text-sm font-medium text-gray-700\">Plan actual</p>\n            <p className=\"text-xs text-gray-400 mt-0.5 capitalize\">{business.plan} · {business.subscription_status}</p>\n          </div>\n          <span className=\"badge bg-gray-200 text-gray-600 capitalize\">{business.plan}</span>\n        </div>\n        <div className=\"mt-3 pt-3 border-t border-gray-200\">\n          <p className=\"text-xs text-gray-400 font-mono\">\n            Slug: <span className=\"text-gray-600\">{business.slug}</span>\n          </p>\n          <p className=\"text-xs text-gray-400 font-mono mt-1\">\n            ID: <span className=\"text-gray-600\">{business.id}</span>\n          </p>\n        </div>\n      </div>\n\n      {/* Error */}\n      {error && (\n        <div className=\"rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700\">{error}</div>\n      )}\n\n      {/* Guardar */}\n      <div className=\"flex items-center gap-3 pt-2\">\n        <button\n          type=\"submit\"\n          disabled={saving}\n          className=\"flex items-center gap-2 rounded-xl bg-black px-6 py-2.5 text-sm font-medium\n                     text-white hover:bg-gray-800 transition-colors disabled:opacity-40 active:scale-[0.98]\"\n        >\n          {saving\n            ? <Loader2 size={14} className=\"animate-spin\" />\n            : saved\n              ? <Check size={14} />\n              : null\n          }\n          {saving ? 'Guardando...' : saved ? 'Guardado ✓' : 'Guardar cambios'}\n        </button>\n      </div>\n    </form>\n  )\n}\n\nfunction Section({ title, children }: { title: string; children: React.ReactNode }) {\n  return (\n    <div className=\"bg-white rounded-2xl border border-gray-100 overflow-hidden\">\n      <div className=\"px-5 py-3.5 border-b border-gray-100 bg-gray-50/50\">\n        <p className=\"text-sm font-medium text-gray-700\">{title}</p>\n      </div>\n      <div className=\"p-5 space-y-4\">{children}</div>\n    </div>\n  )\n}\n"

files["app/admin/customers/page.tsx"] = "// app/admin/customers/page.tsx\nimport { createClient } from '@/lib/supabase/server'\nimport { redirect } from 'next/navigation'\nimport { formatPrice, formatDate } from '@/lib/utils'\nimport { Users, Phone, MapPin, ShoppingBag, TrendingUp } from 'lucide-react'\nimport type { Customer } from '@/types'\n\nexport const metadata = { title: 'Clientes' }\n\nexport default async function CustomersPage() {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('business_id, business:businesses(currency)')\n    .eq('user_id', user.id)\n    .single()\n\n  if (!profile?.business_id) redirect('/admin/onboarding')\n\n  const currency = (profile.business as { currency?: string } | null)?.currency ?? 'UYU'\n\n  const { data: customers } = await supabase\n    .from('customers')\n    .select('*')\n    .eq('business_id', profile.business_id)\n    .order('total_orders', { ascending: false })\n\n  const list = (customers ?? []) as Customer[]\n  const totalRevenue = list.reduce((acc, c) => acc + (c.total_spent ?? 0), 0)\n  const totalOrders = list.reduce((acc, c) => acc + (c.total_orders ?? 0), 0)\n\n  return (\n    <div className=\"space-y-6 animate-fade-in\">\n      {/* Header */}\n      <div>\n        <h1 className=\"text-2xl font-semibold tracking-tight\">Clientes</h1>\n        <p className=\"text-sm text-gray-400 mt-0.5\">{list.length} registrados</p>\n      </div>\n\n      {/* Resumen rápido */}\n      {list.length > 0 && (\n        <div className=\"grid grid-cols-3 gap-4\">\n          {[\n            { label: 'Total clientes', value: list.length, icon: Users },\n            { label: 'Pedidos totales', value: totalOrders, icon: ShoppingBag },\n            { label: 'Facturación total', value: formatPrice(totalRevenue, currency), icon: TrendingUp },\n          ].map(({ label, value, icon: Icon }) => (\n            <div key={label} className=\"bg-white rounded-2xl border border-gray-100 p-5\">\n              <div className=\"flex items-center justify-between mb-3\">\n                <p className=\"text-xs text-gray-400\">{label}</p>\n                <Icon size={14} className=\"text-gray-300\" />\n              </div>\n              <p className=\"text-2xl font-semibold text-gray-900 tracking-tight\">{value}</p>\n            </div>\n          ))}\n        </div>\n      )}\n\n      {/* Lista */}\n      {list.length === 0 ? (\n        <div className=\"rounded-2xl border-2 border-dashed border-gray-200 p-16 text-center\">\n          <Users size={28} className=\"mx-auto text-gray-200 mb-3\" />\n          <p className=\"text-sm font-medium text-gray-400\">Sin clientes todavía</p>\n          <p className=\"text-xs text-gray-300 mt-1\">\n            Los clientes se registran automáticamente cuando hacen un pedido\n          </p>\n        </div>\n      ) : (\n        <div className=\"bg-white rounded-2xl border border-gray-100 overflow-hidden\">\n          {/* Desktop */}\n          <div className=\"hidden sm:block overflow-x-auto\">\n            <table className=\"w-full\">\n              <thead>\n                <tr className=\"border-b border-gray-100\">\n                  {['Cliente', 'Teléfono', 'Dirección', 'Pedidos', 'Total gastado'].map(h => (\n                    <th key={h} className=\"text-left text-xs font-medium text-gray-400 px-5 py-3.5\">\n                      {h}\n                    </th>\n                  ))}\n                </tr>\n              </thead>\n              <tbody>\n                {list.map((customer, i) => (\n                  <tr key={customer.id}\n                    className=\"border-b border-gray-50 last:border-0 hover:bg-gray-50/40 transition-colors\">\n                    <td className=\"px-5 py-4\">\n                      <div className=\"flex items-center gap-3\">\n                        <div className=\"h-8 w-8 rounded-full bg-gray-100 flex items-center justify-center\n                                        text-xs font-semibold text-gray-500 shrink-0\">\n                          {customer.name.slice(0, 1).toUpperCase()}\n                        </div>\n                        <div>\n                          <p className=\"text-sm font-medium text-gray-900\">{customer.name}</p>\n                          {customer.email && (\n                            <p className=\"text-xs text-gray-400\">{customer.email}</p>\n                          )}\n                        </div>\n                      </div>\n                    </td>\n                    <td className=\"px-5 py-4\">\n                      {customer.phone ? (\n                        <a href={`https://wa.me/${customer.phone.replace(/\\D/g, '')}`}\n                          target=\"_blank\"\n                          className=\"flex items-center gap-1.5 text-sm text-gray-600 hover:text-green-600 transition-colors w-fit\">\n                          <Phone size={12} />\n                          {customer.phone}\n                        </a>\n                      ) : (\n                        <span className=\"text-sm text-gray-300\">—</span>\n                      )}\n                    </td>\n                    <td className=\"px-5 py-4 max-w-[180px]\">\n                      {customer.address ? (\n                        <p className=\"text-sm text-gray-600 truncate\" title={customer.address}>\n                          {customer.address}\n                        </p>\n                      ) : (\n                        <span className=\"text-sm text-gray-300\">—</span>\n                      )}\n                    </td>\n                    <td className=\"px-5 py-4\">\n                      <div className=\"flex items-center gap-1.5\">\n                        <span className=\"text-sm font-semibold text-gray-900\">{customer.total_orders}</span>\n                        <span className=\"text-xs text-gray-400\">pedidos</span>\n                      </div>\n                    </td>\n                    <td className=\"px-5 py-4\">\n                      <p className=\"text-sm font-semibold text-gray-900\">\n                        {formatPrice(customer.total_spent ?? 0, currency)}\n                      </p>\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n\n          {/* Mobile */}\n          <div className=\"sm:hidden divide-y divide-gray-50\">\n            {list.map(customer => (\n              <div key={customer.id} className=\"px-4 py-4\">\n                <div className=\"flex items-center justify-between mb-2\">\n                  <div className=\"flex items-center gap-2.5\">\n                    <div className=\"h-8 w-8 rounded-full bg-gray-100 flex items-center justify-center\n                                    text-xs font-semibold text-gray-500 shrink-0\">\n                      {customer.name.slice(0, 1).toUpperCase()}\n                    </div>\n                    <p className=\"text-sm font-medium text-gray-900\">{customer.name}</p>\n                  </div>\n                  <p className=\"text-sm font-bold text-gray-900\">\n                    {formatPrice(customer.total_spent ?? 0, currency)}\n                  </p>\n                </div>\n                <div className=\"flex items-center gap-4 pl-10\">\n                  {customer.phone && (\n                    <a href={`https://wa.me/${customer.phone.replace(/\\D/g, '')}`}\n                      target=\"_blank\"\n                      className=\"flex items-center gap-1 text-xs text-gray-400 hover:text-green-600\">\n                      <Phone size={11} /> {customer.phone}\n                    </a>\n                  )}\n                  <span className=\"text-xs text-gray-400\">\n                    {customer.total_orders} {customer.total_orders === 1 ? 'pedido' : 'pedidos'}\n                  </span>\n                </div>\n              </div>\n            ))}\n          </div>\n        </div>\n      )}\n    </div>\n  )\n}\n"

files["app/admin/ai/page.tsx"] = "// app/admin/ai/page.tsx\nimport { createClient } from '@/lib/supabase/server'\nimport { redirect } from 'next/navigation'\nimport AIAssistant from './AIAssistant'\nimport { Sparkles, Lock } from 'lucide-react'\n\nexport const metadata = { title: 'IA' }\n\nexport default async function AIPage() {\n  const supabase = await createClient()\n  const { data: { user } } = await supabase.auth.getUser()\n  if (!user) redirect('/auth/login')\n\n  const { data: profile } = await supabase\n    .from('profiles')\n    .select('business_id, business:businesses(name, plan)')\n    .eq('user_id', user.id)\n    .single()\n\n  if (!profile?.business_id) redirect('/admin/onboarding')\n\n  const biz = profile.business as { name: string; plan: string } | null\n  const hasPro = biz?.plan === 'pro' || biz?.plan === 'premium'\n\n  return (\n    <div className=\"space-y-6 animate-fade-in\">\n      <div className=\"flex items-center gap-3\">\n        <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br from-violet-500 to-purple-600\">\n          <Sparkles size={18} className=\"text-white\" />\n        </div>\n        <div>\n          <h1 className=\"text-2xl font-semibold tracking-tight\">IA Assistant</h1>\n          <p className=\"text-sm text-gray-400 mt-0.5\">Creá productos, promos e insights con IA</p>\n        </div>\n      </div>\n\n      {!hasPro ? (\n        /* Plan insuficiente */\n        <div className=\"rounded-2xl border-2 border-dashed border-purple-100 bg-purple-50/40 p-12 text-center\">\n          <div className=\"flex h-12 w-12 items-center justify-center rounded-2xl bg-purple-100 mx-auto mb-4\">\n            <Lock size={20} className=\"text-purple-500\" />\n          </div>\n          <p className=\"font-semibold text-gray-900 mb-1\">Requiere plan Pro o Premium</p>\n          <p className=\"text-sm text-gray-500 max-w-sm mx-auto\">\n            La IA está disponible a partir del plan Pro. Contactá soporte para actualizar tu suscripción.\n          </p>\n          <div className=\"mt-6 inline-flex items-center gap-2 rounded-xl bg-purple-600 px-5 py-2.5\n                          text-sm font-medium text-white opacity-60 cursor-not-allowed\">\n            <Sparkles size={14} /> Actualizar a Pro\n          </div>\n        </div>\n      ) : (\n        <AIAssistant\n          businessId={profile.business_id}\n          businessName={biz?.name ?? 'Mi comercio'}\n        />\n      )}\n    </div>\n  )\n}\n"

files["app/admin/ai/AIAssistant.tsx"] = "// app/admin/ai/AIAssistant.tsx\n'use client'\nimport { useState } from 'react'\nimport { useRouter } from 'next/navigation'\nimport { createClient } from '@/lib/supabase/client'\nimport { slugify } from '@/lib/utils'\nimport {\n  Sparkles, Loader2, Check, ChevronDown, ChevronUp,\n  Package, Megaphone, BarChart2, Copy, Save, RefreshCw,\n} from 'lucide-react'\nimport { cn } from '@/lib/utils'\nimport type { AIProductOutput } from '@/types'\n\ntype Tab = 'product' | 'promo' | 'insights'\n\nexport default function AIAssistant({\n  businessId,\n  businessName,\n}: {\n  businessId: string\n  businessName: string\n}) {\n  const [tab, setTab] = useState<Tab>('product')\n\n  return (\n    <div className=\"space-y-5\">\n      {/* Tabs */}\n      <div className=\"flex items-center gap-2 bg-gray-100 rounded-2xl p-1 w-fit\">\n        {([\n          { key: 'product', label: 'Crear producto', icon: Package },\n          { key: 'promo',   label: 'Generar promo',  icon: Megaphone },\n          { key: 'insights',label: 'Insights',        icon: BarChart2 },\n        ] as { key: Tab; label: string; icon: React.ElementType }[]).map(({ key, label, icon: Icon }) => (\n          <button\n            key={key}\n            onClick={() => setTab(key)}\n            className={cn(\n              'flex items-center gap-2 rounded-xl px-4 py-2 text-sm font-medium transition-all',\n              tab === key\n                ? 'bg-white text-gray-900 shadow-sm'\n                : 'text-gray-500 hover:text-gray-700'\n            )}\n          >\n            <Icon size={14} />\n            {label}\n          </button>\n        ))}\n      </div>\n\n      {/* Contenido */}\n      {tab === 'product' && (\n        <ProductGenerator businessId={businessId} businessName={businessName} />\n      )}\n      {tab === 'promo' && (\n        <PromoGenerator businessName={businessName} />\n      )}\n      {tab === 'insights' && (\n        <InsightsGenerator businessId={businessId} businessName={businessName} />\n      )}\n    </div>\n  )\n}\n\n// ── Generador de productos ─────────────────────────────────────────────────\n\nfunction ProductGenerator({\n  businessId,\n  businessName,\n}: {\n  businessId: string\n  businessName: string\n}) {\n  const router = useRouter()\n  const supabase = createClient()\n\n  const [input, setInput] = useState('')\n  const [businessType, setBusinessType] = useState('')\n  const [loading, setLoading] = useState(false)\n  const [error, setError] = useState<string | null>(null)\n  const [result, setResult] = useState<AIProductOutput | null>(null)\n  const [saving, setSaving] = useState(false)\n  const [saved, setSaved] = useState(false)\n  const [showCopy, setShowCopy] = useState<string | null>(null)\n\n  // Campos editables del resultado\n  const [editName, setEditName] = useState('')\n  const [editDesc, setEditDesc] = useState('')\n  const [editPrice, setEditPrice] = useState('')\n\n  async function generate() {\n    if (!input.trim()) return\n    setLoading(true)\n    setError(null)\n    setResult(null)\n    setSaved(false)\n\n    try {\n      const res = await fetch('/api/ai/product', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ rawText: input.trim(), businessType: businessType.trim() }),\n      })\n      const data = await res.json()\n      if (!res.ok) throw new Error(data.error ?? 'Error de IA')\n      setResult(data as AIProductOutput)\n      setEditName(data.name)\n      setEditDesc(data.description)\n      setEditPrice('')\n    } catch (e: unknown) {\n      setError(e instanceof Error ? e.message : 'Error desconocido')\n    } finally {\n      setLoading(false)\n    }\n  }\n\n  async function saveProduct() {\n    if (!result || !editPrice) return\n    setSaving(true)\n    const slug = slugify(editName) + '-' + Math.random().toString(36).slice(2, 5)\n    const { error } = await supabase.from('products').insert({\n      business_id: businessId,\n      name: editName,\n      slug,\n      description: editDesc,\n      price: parseFloat(editPrice),\n      tags: result.tags,\n      seo_title: result.seo_title,\n      seo_desc: result.seo_description,\n      active: true,\n      featured: false,\n      images: [],\n    })\n    if (!error) {\n      setSaved(true)\n      router.push('/admin/products')\n      router.refresh()\n    }\n    setSaving(false)\n  }\n\n  function copy(text: string, key: string) {\n    navigator.clipboard.writeText(text)\n    setShowCopy(key)\n    setTimeout(() => setShowCopy(null), 2000)\n  }\n\n  return (\n    <div className=\"space-y-5\">\n      {/* Input */}\n      <div className=\"bg-white rounded-2xl border border-gray-100 p-5 space-y-4\">\n        <div>\n          <label className=\"field-label\">\n            Describí tu producto en lenguaje natural\n          </label>\n          <textarea\n            value={input}\n            onChange={e => setInput(e.target.value)}\n            placeholder={'Ej: \"Hamburguesa doble cheddar con panceta crocante $390\"\\n\"Remera oversize negra premium talle M/L/XL $1200\"\\n\"Café con leche grande con un croissant $280\"'}\n            rows={4}\n            className=\"input-base resize-none\"\n          />\n        </div>\n        <div>\n          <label className=\"field-label\">\n            Tipo de negocio <span className=\"text-gray-400 font-normal text-xs\">(opcional)</span>\n          </label>\n          <input\n            type=\"text\"\n            value={businessType}\n            onChange={e => setBusinessType(e.target.value)}\n            placeholder=\"Ej: hamburguesería, cafetería, streetwear, ferretería...\"\n            className=\"input-base\"\n          />\n        </div>\n\n        {error && (\n          <div className=\"rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700\">{error}</div>\n        )}\n\n        <button\n          onClick={generate}\n          disabled={loading || !input.trim()}\n          className=\"flex items-center gap-2 rounded-xl bg-gradient-to-r from-violet-600 to-purple-600\n                     px-5 py-2.5 text-sm font-medium text-white hover:opacity-90\n                     transition-opacity disabled:opacity-40 active:scale-[0.98]\"\n        >\n          {loading\n            ? <Loader2 size={14} className=\"animate-spin\" />\n            : <Sparkles size={14} />\n          }\n          {loading ? 'Generando...' : 'Generar con IA'}\n        </button>\n      </div>\n\n      {/* Resultado */}\n      {result && (\n        <div className=\"bg-white rounded-2xl border border-purple-100 overflow-hidden animate-slide-up\">\n          <div className=\"bg-gradient-to-r from-violet-50 to-purple-50 px-5 py-3.5 border-b border-purple-100\">\n            <div className=\"flex items-center gap-2\">\n              <Sparkles size={14} className=\"text-purple-600\" />\n              <p className=\"text-sm font-medium text-purple-800\">Resultado generado</p>\n            </div>\n          </div>\n\n          <div className=\"p-5 space-y-5\">\n            {/* Nombre + descripción editables */}\n            <div className=\"space-y-3\">\n              <div>\n                <label className=\"field-label\">Nombre del producto</label>\n                <input type=\"text\" value={editName} onChange={e => setEditName(e.target.value)}\n                  className=\"input-base font-medium\" />\n              </div>\n              <div>\n                <label className=\"field-label\">Descripción</label>\n                <textarea value={editDesc} onChange={e => setEditDesc(e.target.value)}\n                  rows={3} className=\"input-base resize-none\" />\n              </div>\n              <div>\n                <label className=\"field-label\">\n                  Precio <span className=\"text-red-400\">*</span>\n                  <span className=\"text-xs text-gray-400 font-normal ml-1\">(requerido para guardar)</span>\n                </label>\n                <input type=\"number\" min=\"0\" step=\"0.01\" value={editPrice}\n                  onChange={e => setEditPrice(e.target.value)}\n                  placeholder=\"Ingresá el precio\" className=\"input-base\" />\n              </div>\n            </div>\n\n            {/* Tags */}\n            <div>\n              <p className=\"text-xs font-medium text-gray-500 mb-2\">Tags</p>\n              <div className=\"flex flex-wrap gap-1.5\">\n                {result.tags.map(tag => (\n                  <span key={tag} className=\"rounded-lg bg-gray-100 px-2.5 py-1 text-xs text-gray-600\">\n                    {tag}\n                  </span>\n                ))}\n              </div>\n            </div>\n\n            {/* Copy sections */}\n            {[\n              { key: 'ig', label: '📸 Instagram', text: result.instagram_copy },\n              { key: 'wa', label: '💬 WhatsApp', text: result.whatsapp_copy },\n              { key: 'hash', label: '#️⃣ Hashtags', text: result.hashtags.join(' ') },\n              { key: 'seo_t', label: '🔍 SEO Title', text: result.seo_title },\n              { key: 'seo_d', label: '🔍 SEO Description', text: result.seo_description },\n            ].map(({ key, label, text }) => (\n              <div key={key}>\n                <div className=\"flex items-center justify-between mb-1.5\">\n                  <p className=\"text-xs font-medium text-gray-500\">{label}</p>\n                  <button onClick={() => copy(text, key)}\n                    className=\"flex items-center gap-1 rounded-lg px-2 py-1 text-xs text-gray-400\n                               hover:bg-gray-100 hover:text-gray-700 transition-colors\">\n                    {showCopy === key ? <Check size={11} className=\"text-green-600\" /> : <Copy size={11} />}\n                    {showCopy === key ? 'Copiado' : 'Copiar'}\n                  </button>\n                </div>\n                <div className=\"rounded-xl bg-gray-50 border border-gray-100 px-3.5 py-2.5 text-sm text-gray-700\">\n                  {text}\n                </div>\n              </div>\n            ))}\n\n            {/* Acciones */}\n            <div className=\"flex items-center gap-3 pt-2 border-t border-gray-100\">\n              <button\n                onClick={saveProduct}\n                disabled={saving || !editPrice || saved}\n                className=\"flex items-center gap-2 rounded-xl bg-black px-5 py-2.5 text-sm font-medium\n                           text-white hover:bg-gray-800 disabled:opacity-40 transition-colors active:scale-[0.98]\"\n              >\n                {saving\n                  ? <Loader2 size={14} className=\"animate-spin\" />\n                  : saved\n                    ? <Check size={14} />\n                    : <Save size={14} />\n                }\n                {saving ? 'Guardando...' : saved ? 'Guardado ✓' : 'Guardar producto'}\n              </button>\n              <button\n                onClick={() => { setResult(null); setInput('') }}\n                className=\"flex items-center gap-2 rounded-xl border border-gray-200 px-4 py-2.5\n                           text-sm text-gray-500 hover:bg-gray-50 transition-colors\"\n              >\n                <RefreshCw size={13} /> Nuevo\n              </button>\n            </div>\n          </div>\n        </div>\n      )}\n    </div>\n  )\n}\n\n// ── Generador de promos ────────────────────────────────────────────────────\n\nfunction PromoGenerator({ businessName }: { businessName: string }) {\n  const [context, setContext] = useState('')\n  const [loading, setLoading] = useState(false)\n  const [error, setError] = useState<string | null>(null)\n  const [result, setResult] = useState<{\n    title: string\n    body: string\n    instagram_story: string\n    whatsapp_message: string\n    cta: string\n  } | null>(null)\n  const [showCopy, setShowCopy] = useState<string | null>(null)\n\n  async function generate() {\n    if (!context.trim()) return\n    setLoading(true)\n    setError(null)\n    setResult(null)\n    try {\n      const res = await fetch('/api/ai/promo', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ context: context.trim(), businessName }),\n      })\n      const data = await res.json()\n      if (!res.ok) throw new Error(data.error ?? 'Error de IA')\n      setResult(data)\n    } catch (e: unknown) {\n      setError(e instanceof Error ? e.message : 'Error')\n    } finally {\n      setLoading(false)\n    }\n  }\n\n  function copy(text: string, key: string) {\n    navigator.clipboard.writeText(text)\n    setShowCopy(key)\n    setTimeout(() => setShowCopy(null), 2000)\n  }\n\n  return (\n    <div className=\"space-y-5\">\n      <div className=\"bg-white rounded-2xl border border-gray-100 p-5 space-y-4\">\n        <div>\n          <label className=\"field-label\">¿Qué querés promocionar?</label>\n          <textarea\n            value={context}\n            onChange={e => setContext(e.target.value)}\n            placeholder={'Ej: \"2x1 en hamburguesas los martes\"\\n\"Liquidación de temporada ropa de verano\"\\n\"Promo del día: café + medialunas por $150\"'}\n            rows={4}\n            className=\"input-base resize-none\"\n          />\n        </div>\n        {error && (\n          <div className=\"rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700\">{error}</div>\n        )}\n        <button\n          onClick={generate}\n          disabled={loading || !context.trim()}\n          className=\"flex items-center gap-2 rounded-xl bg-gradient-to-r from-orange-500 to-pink-500\n                     px-5 py-2.5 text-sm font-medium text-white hover:opacity-90\n                     transition-opacity disabled:opacity-40 active:scale-[0.98]\"\n        >\n          {loading ? <Loader2 size={14} className=\"animate-spin\" /> : <Megaphone size={14} />}\n          {loading ? 'Generando...' : 'Crear promo'}\n        </button>\n      </div>\n\n      {result && (\n        <div className=\"bg-white rounded-2xl border border-orange-100 overflow-hidden animate-slide-up\">\n          <div className=\"bg-gradient-to-r from-orange-50 to-pink-50 px-5 py-3.5 border-b border-orange-100\">\n            <p className=\"text-sm font-semibold text-orange-800\">{result.title}</p>\n          </div>\n          <div className=\"p-5 space-y-4\">\n            <p className=\"text-sm text-gray-700\">{result.body}</p>\n            {[\n              { key: 'ig', label: '📸 Historia de Instagram', text: result.instagram_story },\n              { key: 'wa', label: '💬 Mensaje WhatsApp', text: result.whatsapp_message },\n              { key: 'cta', label: '🎯 CTA', text: result.cta },\n            ].map(({ key, label, text }) => (\n              <div key={key}>\n                <div className=\"flex items-center justify-between mb-1.5\">\n                  <p className=\"text-xs font-medium text-gray-500\">{label}</p>\n                  <button onClick={() => copy(text, key)}\n                    className=\"flex items-center gap-1 rounded-lg px-2 py-1 text-xs text-gray-400\n                               hover:bg-gray-100 hover:text-gray-700 transition-colors\">\n                    {showCopy === key ? <Check size={11} className=\"text-green-600\" /> : <Copy size={11} />}\n                    {showCopy === key ? 'Copiado' : 'Copiar'}\n                  </button>\n                </div>\n                <div className=\"rounded-xl bg-gray-50 border border-gray-100 px-3.5 py-2.5 text-sm text-gray-700\">\n                  {text}\n                </div>\n              </div>\n            ))}\n            <button onClick={() => setResult(null)}\n              className=\"flex items-center gap-2 rounded-xl border border-gray-200 px-4 py-2 text-sm text-gray-500 hover:bg-gray-50\">\n              <RefreshCw size={13} /> Generar otra\n            </button>\n          </div>\n        </div>\n      )}\n    </div>\n  )\n}\n\n// ── Insights ───────────────────────────────────────────────────────────────\n\nfunction InsightsGenerator({\n  businessId,\n  businessName,\n}: {\n  businessId: string\n  businessName: string\n}) {\n  const [loading, setLoading] = useState(false)\n  const [insights, setInsights] = useState<string[] | null>(null)\n  const [error, setError] = useState<string | null>(null)\n\n  async function generate() {\n    setLoading(true)\n    setError(null)\n    setInsights(null)\n    try {\n      const res = await fetch('/api/ai/insights', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ businessId }),\n      })\n      const data = await res.json()\n      if (!res.ok) throw new Error(data.error ?? 'Error de IA')\n      setInsights(data.insights)\n    } catch (e: unknown) {\n      setError(e instanceof Error ? e.message : 'Error')\n    } finally {\n      setLoading(false)\n    }\n  }\n\n  return (\n    <div className=\"space-y-5\">\n      <div className=\"bg-white rounded-2xl border border-gray-100 p-5\">\n        <p className=\"text-sm text-gray-600 mb-4\">\n          La IA analiza tus pedidos, productos y clientes para darte recomendaciones\n          prácticas sobre cómo mejorar tu negocio hoy.\n        </p>\n        <button\n          onClick={generate}\n          disabled={loading}\n          className=\"flex items-center gap-2 rounded-xl bg-gradient-to-r from-teal-500 to-green-500\n                     px-5 py-2.5 text-sm font-medium text-white hover:opacity-90\n                     transition-opacity disabled:opacity-40 active:scale-[0.98]\"\n        >\n          {loading ? <Loader2 size={14} className=\"animate-spin\" /> : <BarChart2 size={14} />}\n          {loading ? 'Analizando...' : 'Analizar mi negocio'}\n        </button>\n        {error && (\n          <p className=\"text-sm text-red-600 mt-3\">{error}</p>\n        )}\n      </div>\n\n      {insights && (\n        <div className=\"space-y-3 animate-slide-up\">\n          {insights.map((insight, i) => (\n            <div key={i}\n              className=\"flex items-start gap-3 bg-white rounded-2xl border border-teal-100 px-5 py-4\">\n              <div className=\"flex h-6 w-6 shrink-0 items-center justify-center rounded-full\n                              bg-teal-100 text-xs font-bold text-teal-700 mt-0.5\">\n                {i + 1}\n              </div>\n              <p className=\"text-sm text-gray-700 leading-relaxed\">{insight}</p>\n            </div>\n          ))}\n          <button onClick={() => setInsights(null)}\n            className=\"flex items-center gap-2 rounded-xl border border-gray-200 px-4 py-2 text-sm text-gray-500 hover:bg-gray-50\">\n            <RefreshCw size={13} /> Volver a analizar\n          </button>\n        </div>\n      )}\n    </div>\n  )\n}\n"

files["app/api/ai/promo/route.ts"] = "// app/api/ai/promo/route.ts\nimport { createClient } from '@/lib/supabase/server'\nimport { generatePromoAI } from '@/lib/ai'\nimport { NextResponse } from 'next/server'\n\nexport async function POST(req: Request) {\n  try {\n    const supabase = await createClient()\n    const { data: { user } } = await supabase.auth.getUser()\n    if (!user) return NextResponse.json({ error: 'No autorizado' }, { status: 401 })\n\n    const { data: profile } = await supabase\n      .from('profiles')\n      .select('business_id, business:businesses(name, plan)')\n      .eq('user_id', user.id)\n      .single()\n\n    const biz = profile?.business as { name: string; plan: string } | null\n    if (!biz || !['pro', 'premium'].includes(biz.plan))\n      return NextResponse.json({ error: 'Requiere plan Pro o Premium' }, { status: 403 })\n\n    const { context } = await req.json()\n    if (!context?.trim())\n      return NextResponse.json({ error: 'Contexto requerido' }, { status: 400 })\n\n    const result = await generatePromoAI(biz.name, context)\n\n    await supabase.from('ai_generations').insert({\n      business_id: profile!.business_id,\n      type: 'promo',\n      input: { context },\n      output: result,\n    })\n\n    return NextResponse.json(result)\n  } catch (err) {\n    console.error(err)\n    return NextResponse.json({ error: 'Error generando con IA' }, { status: 500 })\n  }\n}\n"

files["app/api/ai/insights/route.ts"] = "// app/api/ai/insights/route.ts\nimport { createClient } from '@/lib/supabase/server'\nimport { createServiceClient } from '@/lib/supabase/server'\nimport { generateInsightsAI } from '@/lib/ai'\nimport { NextResponse } from 'next/server'\n\nexport async function POST(req: Request) {\n  try {\n    const supabase = await createClient()\n    const { data: { user } } = await supabase.auth.getUser()\n    if (!user) return NextResponse.json({ error: 'No autorizado' }, { status: 401 })\n\n    const { data: profile } = await supabase\n      .from('profiles')\n      .select('business_id, business:businesses(name, plan)')\n      .eq('user_id', user.id)\n      .single()\n\n    const biz = profile?.business as { name: string; plan: string } | null\n    if (!biz || !['pro', 'premium'].includes(biz.plan))\n      return NextResponse.json({ error: 'Requiere plan Pro o Premium' }, { status: 403 })\n\n    const businessId = profile!.business_id\n    const service = createServiceClient()\n\n    // Recopilar stats reales\n    const [ordersRes, productsRes, customersRes] = await Promise.all([\n      service.from('orders').select('status, confirmed_sale, total').eq('business_id', businessId),\n      service.from('products').select('id', { count: 'exact', head: true }).eq('business_id', businessId).eq('active', true),\n      service.from('customers').select('id', { count: 'exact', head: true }).eq('business_id', businessId),\n    ])\n\n    const orders = ordersRes.data ?? []\n    const pendingOrders = orders.filter(o => o.status === 'pending').length\n    const confirmedOrders = orders.filter(o => o.confirmed_sale).length\n    const cancelledOrders = orders.filter(o => o.status === 'cancelled').length\n    const totalRevenue = orders.filter(o => o.confirmed_sale).reduce((acc, o) => acc + (o.total ?? 0), 0)\n    const cancelRate = orders.length > 0 ? Math.round((cancelledOrders / orders.length) * 100) : 0\n\n    // Top productos (simplificado)\n    const { data: topItems } = await service\n      .from('order_items')\n      .select('product_name, quantity')\n      .limit(100)\n\n    const productCounts: Record<string, number> = {}\n    ;(topItems ?? []).forEach(item => {\n      productCounts[item.product_name] = (productCounts[item.product_name] ?? 0) + item.quantity\n    })\n    const topProducts = Object.entries(productCounts)\n      .sort((a, b) => b[1] - a[1])\n      .slice(0, 5)\n      .map(([name, count]) => ({ name, count, revenue: 0 }))\n\n    const stats = {\n      pendingOrders,\n      confirmedOrders,\n      totalRevenue,\n      totalCustomers: customersRes.count ?? 0,\n      totalProducts: productsRes.count ?? 0,\n      topProducts,\n      cancelRate,\n      todayRevenue: 0,\n      recentOrders: [],\n    }\n\n    const insights = await generateInsightsAI(biz.name, stats)\n\n    await supabase.from('ai_generations').insert({\n      business_id: businessId,\n      type: 'insights',\n      input: { stats },\n      output: { insights },\n    })\n\n    return NextResponse.json({ insights })\n  } catch (err) {\n    console.error(err)\n    return NextResponse.json({ error: 'Error generando insights' }, { status: 500 })\n  }\n}\n"

files["app/globals.css"] = "@tailwind base;\n@tailwind components;\n@tailwind utilities;\n\n@layer base {\n  :root { --brand-primary: #000000; --brand-secondary: #ffffff; }\n  * { box-sizing: border-box; }\n  html { -webkit-font-smoothing: antialiased; }\n  body { @apply bg-white text-gray-900; }\n}\n\n@layer components {\n  .input-base {\n    @apply w-full rounded-xl border border-gray-200 bg-white px-4 py-3 text-sm\n           placeholder:text-gray-400 focus:outline-none focus:ring-2 focus:ring-black/10\n           focus:border-gray-400 transition-all duration-150;\n  }\n  .btn-brand {\n    @apply inline-flex items-center justify-center gap-2 rounded-xl px-5 py-3 text-sm font-medium\n           transition-all duration-150 active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed;\n    background: var(--brand-primary);\n    color: var(--brand-secondary);\n  }\n  .btn-secondary {\n    @apply inline-flex items-center justify-center gap-2 rounded-xl border border-gray-200\n           bg-white px-5 py-3 text-sm font-medium text-gray-700\n           hover:bg-gray-50 transition-all duration-150 active:scale-[0.98];\n  }\n  .card { @apply rounded-2xl border border-gray-100 bg-white p-5 shadow-sm; }\n  .badge { @apply inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium; }\n}\n\n::-webkit-scrollbar { width: 4px; height: 4px; }\n::-webkit-scrollbar-track { background: transparent; }\n::-webkit-scrollbar-thumb { background: #e5e7eb; border-radius: 2px; }\n\n@layer components {\n  .field-label {\n    @apply block text-sm font-medium text-gray-700 mb-1.5;\n  }\n}\n"

let created = 0
for (const [filePath, content] of Object.entries(files)) {
  const dir = path.dirname(filePath)
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true })
  fs.writeFileSync(filePath, content, 'utf8')
  console.log('  ✅ ' + filePath)
  created++
}
console.log('\n✨ ' + created + ' archivos creados.')
